import React from 'react';
import { Typography, List, ListItem, ListItemText } from '@mui/material';

function FailureTrendsPage() {
  const patterns = [
    { reason: 'Timeout during checkout', module_name: 'Checkout API', count: 12 },
    { reason: 'Intermittent 500 on login', module_name: 'Auth Service', count: 9 },
    { reason: 'Search results race condition', module_name: 'Search Module', count: 7 },
  ];

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Failure Trends
      </Typography>
      <List>
        {patterns.map((item, idx) => (
          <ListItem key={idx}>
            <ListItemText primary={item.reason} secondary={`${item.module_name} — ${item.count} occurrences`} />
          </ListItem>
        ))}
      </List>
    </div>
  );
}

export default FailureTrendsPage;
